import json
R,C=22,26
g=[[0]*C for _ in range(R)]
# Outlined rectangles, copied by their border color from the test input geometry.
frames=[(1,6,3,11,1,4),(10,13,2,5,2,8),(9,16,11,21,3,5)]
for r0,r1,c0,c1,border,fill in frames:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1):
                g[r][c]=border
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            if (r-r0-1+c-c0-1)%2==0:
                g[r][c]=fill
assert len(g)==22 and all(len(row)==26 for row in g)
assert [sum(v==color for row in g for v in row) for color in (4,8,5)] == [14,2,27]
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
